55: static inline void
56: bare_fs__request_destroy(bare_fs_req_t *req) {
57:   int err;
58: 
59:   js_env_t *env = req->env;
60: 
61:   js_deferred_teardown_t *teardown = req->teardown;
62: 
63:   uv_fs_req_cleanup(&req->handle);
64: 
65:   err = js_delete_reference(env, req->on_result);
66:   assert(err == 0);
67: 
68:   err = js_delete_reference(env, req->ctx);
69:   assert(err == 0);
70: 
71:   err = js_finish_deferred_teardown_callback(teardown);
72:   assert(err == 0);
73: }
74: 
75: static void
76: bare_fs__on_request_teardown(js_deferred_teardown_t *handle, void *data) {
77:   bare_fs_req_t *req = (bare_fs_req_t *) data;
78: 
79:   req->exiting = true;
80: 
81:   // If a request is still in flight its result callback is guaranteed to run,
82:   // even when the underlying work is cancelled successfully, in which case it
83:   // completes with `UV_ECANCELED`. Destroying the request here would leave that
84:   // pending callback to operate on freed memory, so we only attempt to cancel
85:   // the work to hurry it along and defer destruction to the result callback.
86:   if (req->inflight) {
87:     uv_cancel((uv_req_t *) &req->handle);
88: 
89:     return;
90:   }
91: 
92:   bare_fs__request_destroy(req);
93: }
