95: static inline void
96: bare_fs__on_request_result(uv_fs_t *handle) {
97:   int err;
98: 
99:   bare_fs_req_t *req = (bare_fs_req_t *) handle;
100: 
101:   req->inflight = false;
102: 
103:   if (req->exiting) return bare_fs__request_destroy(req);
104: 
105:   js_env_t *env = req->env;
106: 
107:   js_handle_scope_t *scope;
108:   err = js_open_handle_scope(env, &scope);
109:   assert(err == 0);
110: 
111:   js_value_t *ctx;
112:   err = js_get_reference_value(env, req->ctx, &ctx);
113:   assert(err == 0);
114: 
115:   js_value_t *on_result;
116:   err = js_get_reference_value(env, req->on_result, &on_result);
117:   assert(err == 0);
118: 
119:   int status = handle->result;
120: 
121:   js_value_t *args[2];
122: 
123:   if (status < 0) {
124:     js_value_t *code;
125:     err = js_create_string_utf8(env, (utf8_t *) uv_err_name(status), -1, &code);
126:     assert(err == 0);
127: 
128:     js_value_t *message;
129:     err = js_create_string_utf8(env, (utf8_t *) uv_strerror(status), -1, &message);
130:     assert(err == 0);
131: 
132:     err = js_create_error(env, code, message, &args[0]);
133:     assert(err == 0);
134:   } else {
135:     err = js_get_null(env, &args[0]);
136:     assert(err == 0);
137:   }
138: 
139:   err = js_create_int32(env, status, &args[1]);
140:   assert(err == 0);
141: 
142:   err = js_call_function(env, ctx, on_result, 2, args, NULL);
143:   (void) err;
144: 
145:   err = js_close_handle_scope(env, scope);
146:   assert(err == 0);
147: }
