149: static inline int
150: bare_fs__request_pending(js_env_t *env, bare_fs_req_t *req, bool async, int *result) {
151:   int err;
152: 
153:   if (async) {
154:     req->inflight = true;
155: 
156:     return 0;
157:   }
158: 
159:   int status = req->handle.result;
160: 
161:   if (status < 0) {
162:     err = js_throw_error(env, uv_err_name(status), uv_strerror(status));
163:     assert(err == 0);
164: 
165:     return -1;
166:   }
167: 
168:   if (result) *result = status;
169: 
170:   return 1;
171: }
