677: static inline js_value_t *
678: bare_fs__read(js_env_t *env, js_callback_info_t *info, bool async) {
679:   int err;
680: 
681:   size_t argc = 6;
682:   js_value_t *argv[6];
683: 
684:   err = js_get_callback_info(env, info, &argc, argv, NULL, NULL);
685:   assert(err == 0);
686: 
687:   assert(argc == 6);
688: 
689:   bare_fs_req_t *req;
690:   err = js_get_arraybuffer_info(env, argv[0], (void **) &req, NULL);
691:   assert(err == 0);
692: 
693:   uint32_t fd;
694:   err = js_get_value_uint32(env, argv[1], &fd);
695:   assert(err == 0);
696: 
697:   uint8_t *data;
698:   size_t data_len;
699:   err = js_get_typedarray_info(env, argv[2], NULL, (void **) &data, &data_len, NULL, NULL);
700:   assert(err == 0);
701: 
702:   uint32_t offset;
703:   err = js_get_value_uint32(env, argv[3], &offset);
704:   assert(err == 0);
705: 
706:   uint32_t len;
707:   err = js_get_value_uint32(env, argv[4], &len);
708:   assert(err == 0);
709: 
710:   if (offset >= data_len) len = 0;
711:   else if (offset + len >= data_len) len = data_len - offset;
